const lockDiskQuota = `-- name: LockDiskQuota :exec
SELECT 1 FROM workspaces WHERE id = $1 FOR NO KEY UPDATE
`

// Delete forever, step 0: the workspaces row the quota release will update, locked first — the
// order of an upload (ReserveQuota, then the item under LockDiskTree), so a deletion and an upload
// into the same folder never wait for each other crosswise.
func (q *Queries) LockDiskQuota(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockDiskQuota, id)
	return err
}

const lockDiskTree = `-- name: LockDiskTree :exec
SELECT pg_advisory_xact_lock(hashtext('calaba.disk.' || $1::uuid::text))
`

// Serializes the structural changes of one workspace's Disk (names in a folder, moves and their
// cycle check, restore). Taken after any workspaces row lock of the transaction (an upload
// reserves its quota first), never before one.
func (q *Queries) LockDiskTree(ctx context.Context, workspaceID uuid.UUID) error {
	_, err := q.db.Exec(ctx, lockDiskTree, workspaceID)
	return err
}

const restoreDiskSubtree = `-- name: RestoreDiskSubtree :many
WITH RECURSIVE root AS (
    SELECT r.id, r.trashed_at FROM disk_items r WHERE r.id = $1::uuid AND r.trashed_root
), sub (id) AS (
    SELECT root.id FROM root
    UNION ALL
    SELECT c.id FROM disk_items c JOIN sub ON c.parent_id = sub.id
    WHERE NOT c.trashed_root AND c.trashed_at = (SELECT root.trashed_at FROM root)
)
UPDATE disk_items d SET
    trashed_at   = NULL,
    trashed_by   = NULL,
    trashed_root = false,
    parent_id    = CASE WHEN d.id = $1::uuid THEN $2::uuid ELSE d.parent_id END,
    name         = CASE WHEN d.id = $1::uuid THEN $3::text ELSE d.name END,
    updated_at   = CASE WHEN d.id = $1::uuid THEN now() ELSE d.updated_at END
FROM sub WHERE d.id = sub.id
RETURNING d.id, d.workspace_id, d.parent_id, d.kind, d.name, d.file_id, d.owner_id, d.restricted, d.created_at, d.updated_at, d.trashed_at, d.trashed_by, d.trashed_root
`

type RestoreDiskSubtreeParams struct {
	ID       uuid.UUID
	ParentID *uuid.UUID
	Name     string
}

// Restores a trash root and the part of its subtree trashed with it (same trashed_at, not a
// root of its own). parent_id / name: where the root goes back (the caller picks the root
// when the old parent is gone or in the trash, and «name (2)» on a clash).
func (q *Queries) RestoreDiskSubtree(ctx context.Context, arg RestoreDiskSubtreeParams) ([]DiskItem, error) {
	rows, err := q.db.Query(ctx, restoreDiskSubtree, arg.ID, arg.ParentID, arg.Name)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DiskItem{}
	for rows.Next() {
		var i DiskItem
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ParentID,
			&i.Kind,
			&i.Name,
			&i.FileID,
			&i.OwnerID,
			&i.Restricted,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TrashedAt,
			&i.TrashedBy,
			&i.TrashedRoot,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

