const trashDiskSubtree = `-- name: TrashDiskSubtree :many
WITH RECURSIVE sub (id) AS (
    SELECT d.id FROM disk_items d WHERE d.id = $3::uuid AND d.trashed_at IS NULL
    UNION ALL
    SELECT c.id FROM disk_items c JOIN sub ON c.parent_id = sub.id WHERE c.trashed_at IS NULL
)
UPDATE disk_items d SET
    trashed_at   = $1::timestamptz,
    trashed_by   = $2::uuid,
    trashed_root = (d.id = $3::uuid)
FROM sub WHERE d.id = sub.id
RETURNING d.id, d.workspace_id, d.parent_id, d.kind, d.name, d.file_id, d.owner_id, d.restricted, d.created_at, d.updated_at, d.trashed_at, d.trashed_by, d.trashed_root
`

type TrashDiskSubtreeParams struct {
	TrashedAt time.Time
	TrashedBy *uuid.UUID
	ID        uuid.UUID
}

// Moves an item and its live subtree to the trash in one UPDATE: one timestamp for all, the
// item is the root. Descendants trashed before stay their own roots.
func (q *Queries) TrashDiskSubtree(ctx context.Context, arg TrashDiskSubtreeParams) ([]DiskItem, error) {
	rows, err := q.db.Query(ctx, trashDiskSubtree, arg.TrashedAt, arg.TrashedBy, arg.ID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DiskItem{}
	for rows.Next() {
		var i DiskItem
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ParentID,
			&i.Kind,
			&i.Name,
			&i.FileID,
			&i.OwnerID,
			&i.Restricted,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TrashedAt,
			&i.TrashedBy,
			&i.TrashedRoot,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

